const fs = require('fs');
const path = require('path');

const monaPath = path.join(__dirname, '../apps/web/tmp/mona_lisa_hd.txt');
const screamPath = path.join(__dirname, '../apps/web/tmp/scream_ascii.txt');
const destPath = path.join(__dirname, '../apps/web/app/ascii-art.ts');

const escape = (str) => str
    .replace(/\\/g, '\\\\')
    .replace(/`/g, '\\`')
    .replace(/\$/g, '\\$');

const mona = fs.readFileSync(monaPath, 'utf8').trimEnd();
const scream = fs.readFileSync(screamPath, 'utf8').trimEnd();

const content = `// Generated ASCII art constants
// Do not edit manually. Generated by scripts/create-ascii-module.cjs

export const MONA_LISA_ASCII = \`
${escape(mona)}
\`.trim();

export const SCREAM_ASCII = \`
${escape(scream)}
\`.trim();
`;

fs.writeFileSync(destPath, content, 'utf8');
console.log('Created ascii-art.ts with', content.length, 'bytes');
